-- SYNTHETIC LOCAL DATABASE ONLY. No connection URLs or real identity data.
-- Relation shapes are minimal. Fifteen function bodies below reproduce the reviewed catalogs
-- and applied public hardening, so the real migration's fingerprint guards remain enabled.
-- Raw JSON is not versioned; selected definitions passed the repository secret/PII scanner.
CREATE ROLE anon NOLOGIN;
CREATE ROLE authenticated NOLOGIN;
CREATE ROLE service_role NOLOGIN;
CREATE SCHEMA auth;
CREATE TABLE auth.users (
  id uuid PRIMARY KEY, raw_app_meta_data jsonb NOT NULL DEFAULT '{}'::jsonb,
  deleted_at timestamptz, is_anonymous boolean DEFAULT false, banned_until timestamptz
);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT NULLIF(current_setting('request.jwt.claim.sub', true), '')::uuid
$$;
CREATE TABLE public.businesses (
  id uuid PRIMARY KEY, name text NOT NULL, currency text DEFAULT 'USD',
  tax_rate numeric DEFAULT 0, tax_enabled boolean DEFAULT false,
  allow_negative_inventory boolean DEFAULT false, timezone text DEFAULT 'UTC',
  created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now()
);
CREATE TABLE public.users (
  id uuid PRIMARY KEY, business_id uuid NOT NULL REFERENCES public.businesses(id), employee_id uuid,
  name text, username text, role text, permission_overrides jsonb DEFAULT '{}'::jsonb,
  active boolean DEFAULT true, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now()
);
CREATE TABLE public.role_default_permissions (role text, permission_key text, granted boolean);
CREATE TABLE public.employees (
  id uuid PRIMARY KEY, business_id uuid NOT NULL, name text, job_title text, hourly_rate numeric,
  location_id uuid, manager_id uuid, active boolean DEFAULT true, notes text,
  created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now()
);
CREATE TABLE public.audit_logs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid, user_id uuid,
  user_name_snapshot text, role_snapshot text, action text, details text,
  occurred_at timestamptz DEFAULT now()
);
CREATE TABLE public.business_settings_lists (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid, list_type text, value text,
  active boolean, sort_order integer, created_at timestamptz, updated_at timestamptz
);
CREATE SCHEMA nexalvo_backup;
CREATE SCHEMA nexalvo_platform;
CREATE TABLE nexalvo_platform.operators(user_id uuid PRIMARY KEY, active boolean DEFAULT true, updated_at timestamptz DEFAULT now());
CREATE TABLE nexalvo_platform.provisioning_requests(id uuid PRIMARY KEY);
CREATE TABLE nexalvo_platform.access_audit(
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id uuid, actor_id uuid, action text, active boolean, created_at timestamptz DEFAULT now()
);
ALTER TABLE nexalvo_platform.access_audit ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION nexalvo_platform.audit_operator()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $function$
begin
 insert into nexalvo_platform.access_audit(user_id,actor_id,action,active)
 values(coalesce(new.user_id,old.user_id),auth.uid(),tg_op,case when tg_op='DELETE' then false else new.active end);
 if tg_op='DELETE' then return old; end if;
 new.updated_at=now(); return new;
end; $function$;
CREATE TRIGGER operator_access_audit BEFORE INSERT OR DELETE OR UPDATE ON nexalvo_platform.operators
FOR EACH ROW EXECUTE FUNCTION nexalvo_platform.audit_operator();
-- Definitions follow. Tables, grants and identities are completed at the end of the fixture.

CREATE OR REPLACE FUNCTION nexalvo_platform.has_access()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select auth.uid() is not null and exists(select 1 from nexalvo_platform.operators o join public.users u on u.id=o.user_id where o.user_id=auth.uid() and o.active and u.active);
$function$
;

CREATE OR REPLACE FUNCTION nexalvo_platform.company_directory(p_search text DEFAULT ''::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if not nexalvo_platform.has_access() then raise exception 'Platform access denied' using errcode='42501'; end if;
 if p_search is null or length(p_search)>100 or p_limit is null or p_limit<1 or p_limit>100 or p_offset is null or p_offset<0 or p_offset>100000 then raise exception 'Invalid directory parameters' using errcode='22023'; end if;
 select jsonb_build_object('total',(select count(*) from public.businesses b where strpos(lower(b.name),lower(trim(p_search)))>0),
 'companies',coalesce((select jsonb_agg(to_jsonb(r)) from (
 select b.id,b.name,b.currency,b.timezone,b.created_at,
 (select count(*) from public.users u where u.business_id=b.id and u.active) as active_users,
 (select count(*) from public.locations l where l.business_id=b.id) as locations
 from public.businesses b where strpos(lower(b.name),lower(trim(p_search)))>0 order by b.created_at,b.id limit p_limit offset p_offset
 )r),'[]'::jsonb)) into result;
 return result;
end; $function$
;

CREATE OR REPLACE FUNCTION nexalvo_platform.provision_company(p_request_id uuid, p_name text, p_currency text, p_timezone text, p_location_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_input jsonb; v_existing nexalvo_platform.provisioning_requests%rowtype; v_business_id uuid; v_location_id uuid;
begin
 if not nexalvo_platform.has_access() then raise exception 'Platform access denied' using errcode='42501'; end if;
 if p_request_id is null or p_name is null or length(trim(p_name))<1 or length(trim(p_name))>120
 or p_currency is null or p_currency not in ('USD','BRL','EUR','GBP','CAD','MXN')
 or p_timezone is null or length(p_timezone)>100 or not exists(select 1 from pg_catalog.pg_timezone_names where name=p_timezone)
 or p_location_name is null or length(trim(p_location_name))<1 or length(trim(p_location_name))>80
 then raise exception 'Invalid company parameters' using errcode='22023'; end if;
 v_input=jsonb_build_object('name',trim(p_name),'currency',p_currency,'timezone',p_timezone,'location_name',trim(p_location_name));
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_request_id::text,0));
 select * into v_existing from nexalvo_platform.provisioning_requests where request_id=p_request_id;
 if found then
  if v_existing.operator_id<>auth.uid() or v_existing.input<>v_input then raise exception 'Request identity conflict' using errcode='22023'; end if;
  return jsonb_build_object('business_id',v_existing.business_id,'name',v_input->>'name','owner_pending',not exists(select 1 from public.users u where u.business_id=v_existing.business_id and u.role='OWNER' and u.active),'replayed',true);
 end if;
 insert into public.businesses(name,currency,timezone,tax_rate,tax_enabled,allow_negative_inventory)
 values(trim(p_name),p_currency,p_timezone,0,false,false) returning id into v_business_id;
 insert into public.locations(business_id,name,type,active)
 values(v_business_id,trim(p_location_name),'Retail',true) returning id into v_location_id;
 insert into nexalvo_platform.provisioning_requests(request_id,operator_id,business_id,input)
 values(p_request_id,auth.uid(),v_business_id,v_input);
 insert into nexalvo_platform.company_audit(business_id,actor_id,action,details)
 values(v_business_id,auth.uid(),'company_provisioned',jsonb_build_object('request_id',p_request_id,'location_id',v_location_id,'owner_pending',true));
 return jsonb_build_object('business_id',v_business_id,'name',trim(p_name),'owner_pending',true,'replayed',false);
end; $function$
;

CREATE OR REPLACE FUNCTION nexalvo_platform.assign_first_owner(p_business_id uuid, p_auth_user_id uuid, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_existing public.users%rowtype;
begin
 if not nexalvo_platform.has_access() then raise exception 'Platform access denied' using errcode='42501'; end if;
 if p_business_id is null or p_auth_user_id is null or p_name is null or length(trim(p_name))<1 or length(trim(p_name))>120 then raise exception 'Invalid owner parameters' using errcode='22023'; end if;
 if not exists(select 1 from nexalvo_platform.provisioning_requests where business_id=p_business_id) then raise exception 'Company not provisioned by platform' using errcode='22023'; end if;
 if not nexalvo_platform.eligible_owner_auth(p_auth_user_id) then raise exception 'Account must be confirmed and eligible' using errcode='22023'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('first-owner-business:'||p_business_id::text,0));
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('first-owner-auth:'||p_auth_user_id::text,0));
 select * into v_existing from public.users where id=p_auth_user_id;
 if found then
  if v_existing.business_id=p_business_id and v_existing.role='OWNER' and v_existing.active then
   return jsonb_build_object('business_id',p_business_id,'owner_id',p_auth_user_id,'replayed',true);
  end if;
  raise exception 'Account already linked; existing profiles cannot be moved' using errcode='22023';
 end if;
 if exists(select 1 from public.users where business_id=p_business_id and role='OWNER') then raise exception 'Company already has an owner' using errcode='22023'; end if;
 insert into public.users(id,business_id,name,username,role,permission_overrides,active)
 values(p_auth_user_id,p_business_id,trim(p_name),'owner-'||p_auth_user_id::text,'OWNER','{}'::jsonb,true);
 insert into nexalvo_platform.company_audit(business_id,actor_id,action,details)
 values(p_business_id,auth.uid(),'first_owner_assigned',jsonb_build_object('owner_id',p_auth_user_id));
 return jsonb_build_object('business_id',p_business_id,'owner_id',p_auth_user_id,'replayed',false);
end; $function$
;

CREATE OR REPLACE FUNCTION nexalvo_backup.export_business_data(p_business_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_data jsonb; v_counts jsonb; v_total bigint:=0; v_n bigint;
begin
 if p_business_id is null or not exists(select 1 from public.users u where u.id=auth.uid() and u.business_id=p_business_id and u.role='OWNER' and u.active) then raise exception 'Owner access denied' using errcode='42501'; end if;
select count(*) into v_n from (select 1 from public."audit_logs" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."business_alerts" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."business_counters" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."business_settings_lists" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."businesses" t where t.id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."cash_flow" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."cash_registers" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."customers" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."employees" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."expenses" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."inventory_items" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."inventory_stock" t where exists(select 1 from public.inventory_items p where p.id=t.inventory_item_id and p.business_id=p_business_id) and exists(select 1 from public.locations p where p.id=t.location_id and p.business_id=p_business_id) limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."inventory_transactions" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."locations" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."loyalty_rewards" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."loyalty_transactions" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."product_recipes" t where exists(select 1 from public.products p where p.id=t.product_id and p.business_id=p_business_id) and exists(select 1 from public.inventory_items p where p.id=t.inventory_item_id and p.business_id=p_business_id) limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."products" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."purchase_order_items" t where exists(select 1 from public.purchase_orders p where p.id=t.purchase_order_id and p.business_id=p_business_id) limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."purchase_order_payments" t where exists(select 1 from public.purchase_orders p where p.id=t.purchase_order_id and p.business_id=p_business_id) limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."purchase_orders" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."sale_items" t where exists(select 1 from public.sales p where p.id=t.sale_id and p.business_id=p_business_id) limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."sales" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."shift_breaks" t where exists(select 1 from public.shifts p where p.id=t.shift_id and p.business_id=p_business_id) limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."shifts" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."suppliers" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."task_activity" t where exists(select 1 from public.tasks p where p.id=t.task_id and p.business_id=p_business_id) limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."tasks" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."users" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;
select count(*) into v_n from (select 1 from public."waste_transactions" t where t.business_id=p_business_id limit 10001) bounded; if v_n>10000 then raise exception 'Export exceeds supported row count' using errcode='54000'; end if; v_total:=v_total+v_n;if v_total>50000 then raise exception 'Export exceeds supported total row count' using errcode='54000'; end if;
 select jsonb_build_object('audit_logs',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."user_id" as "user_id",t."user_name_snapshot" as "user_name_snapshot",t."role_snapshot" as "role_snapshot",t."action" as "action",t."details" as "details",t."occurred_at" as "occurred_at" from public."audit_logs" t where t.business_id=p_business_id) r),
'business_alerts',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."key" as "key",t."type" as "type",t."severity" as "severity",t."title" as "title",t."message" as "message",t."entity_type" as "entity_type",t."entity_id" as "entity_id",t."location_id" as "location_id",t."financial" as "financial",t."status" as "status",t."created_at" as "created_at",t."resolved_at" as "resolved_at",t."dismissed_at" as "dismissed_at" from public."business_alerts" t where t.business_id=p_business_id) r),
'business_counters',(select coalesce(jsonb_agg(to_jsonb(r) order by r.counter_name),'[]'::jsonb) from (select t."business_id" as "business_id",t."counter_name" as "counter_name",t."next_value" as "next_value" from public."business_counters" t where t.business_id=p_business_id) r),
'business_settings_lists',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."list_type" as "list_type",t."value" as "value",t."active" as "active",t."sort_order" as "sort_order",t."created_at" as "created_at",t."updated_at" as "updated_at" from public."business_settings_lists" t where t.business_id=p_business_id) r),
'businesses',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."name" as "name",t."currency" as "currency",t."tax_rate"::text as "tax_rate",t."tax_enabled" as "tax_enabled",t."allow_negative_inventory" as "allow_negative_inventory",t."timezone" as "timezone",t."created_at" as "created_at",t."updated_at" as "updated_at" from public."businesses" t where t.id=p_business_id) r),
'cash_flow',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."location_id" as "location_id",t."transaction_date" as "transaction_date",t."type" as "type",t."category" as "category",t."amount"::text as "amount",t."payment_method" as "payment_method",t."description" as "description",t."sale_id" as "sale_id",t."expense_id" as "expense_id",t."purchase_order_payment_id" as "purchase_order_payment_id",t."reversal_of" as "reversal_of",t."status" as "status",t."created_by" as "created_by",t."created_at" as "created_at",t."related_cash_register_id" as "related_cash_register_id" from public."cash_flow" t where t.business_id=p_business_id) r),
'cash_registers',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."location_id" as "location_id",t."status" as "status",t."opened_by" as "opened_by",t."opened_at" as "opened_at",t."opening_cash"::text as "opening_cash",t."closed_by" as "closed_by",t."closed_at" as "closed_at",t."expected_cash"::text as "expected_cash",t."actual_cash"::text as "actual_cash",t."difference"::text as "difference",t."difference_reason" as "difference_reason",t."notes" as "notes",t."created_at" as "created_at",t."updated_at" as "updated_at" from public."cash_registers" t where t.business_id=p_business_id) r),
'customers',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."name" as "name",t."phone" as "phone",t."email" as "email",t."birthday" as "birthday",t."notes" as "notes",t."created_at" as "created_at",t."updated_at" as "updated_at",t."active" as "active" from public."customers" t where t.business_id=p_business_id) r),
'employees',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."name" as "name",t."job_title" as "job_title",t."hourly_rate"::text as "hourly_rate",t."location_id" as "location_id",t."manager_id" as "manager_id",t."active" as "active",t."notes" as "notes",t."created_at" as "created_at",t."updated_at" as "updated_at" from public."employees" t where t.business_id=p_business_id) r),
'expenses',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."location_id" as "location_id",t."expense_date" as "expense_date",t."category" as "category",t."vendor" as "vendor",t."amount"::text as "amount",t."payment_method" as "payment_method",t."recurring" as "recurring",t."description" as "description",t."status" as "status",t."reversed_at" as "reversed_at",t."reversed_by" as "reversed_by",t."created_by" as "created_by",t."created_at" as "created_at" from public."expenses" t where t.business_id=p_business_id) r),
'inventory_items',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."name" as "name",t."sku" as "sku",t."category" as "category",t."unit" as "unit",t."min_qty"::text as "min_qty",t."max_qty"::text as "max_qty",t."supplier_id" as "supplier_id",t."expires_at" as "expires_at",t."notes" as "notes",t."active" as "active",t."created_at" as "created_at",t."updated_at" as "updated_at" from public."inventory_items" t where t.business_id=p_business_id) r),
'inventory_stock',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."inventory_item_id" as "inventory_item_id",t."location_id" as "location_id",t."qty"::text as "qty",t."avg_cost_per_unit"::text as "avg_cost_per_unit",t."last_purchase_cost"::text as "last_purchase_cost",t."last_purchase_date" as "last_purchase_date",t."created_at" as "created_at",t."updated_at" as "updated_at" from public."inventory_stock" t where exists(select 1 from public.inventory_items p where p.id=t.inventory_item_id and p.business_id=p_business_id) and exists(select 1 from public.locations p where p.id=t.location_id and p.business_id=p_business_id)) r),
'inventory_transactions',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."inventory_item_id" as "inventory_item_id",t."location_id" as "location_id",t."type" as "type",t."qty_change"::text as "qty_change",t."unit" as "unit",t."unit_cost"::text as "unit_cost",t."total_cost"::text as "total_cost",t."sale_id" as "sale_id",t."purchase_order_id" as "purchase_order_id",t."related_transaction_id" as "related_transaction_id",t."prev_avg_cost"::text as "prev_avg_cost",t."new_avg_cost"::text as "new_avg_cost",t."note" as "note",t."created_by" as "created_by",t."created_at" as "created_at" from public."inventory_transactions" t where t.business_id=p_business_id) r),
'locations',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."name" as "name",t."type" as "type",t."active" as "active",t."created_at" as "created_at",t."updated_at" as "updated_at" from public."locations" t where t.business_id=p_business_id) r),
'loyalty_rewards',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."name" as "name",t."required_points"::text as "required_points",t."discount_type" as "discount_type",t."discount_value"::text as "discount_value",t."active" as "active",t."created_at" as "created_at",t."updated_at" as "updated_at" from public."loyalty_rewards" t where t.business_id=p_business_id) r),
'loyalty_transactions',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."customer_id" as "customer_id",t."type" as "type",t."points"::text as "points",t."reason" as "reason",t."sale_id" as "sale_id",t."created_by" as "created_by",t."created_at" as "created_at" from public."loyalty_transactions" t where t.business_id=p_business_id) r),
'product_recipes',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."product_id" as "product_id",t."inventory_item_id" as "inventory_item_id",t."qty_per_unit"::text as "qty_per_unit" from public."product_recipes" t where exists(select 1 from public.products p where p.id=t.product_id and p.business_id=p_business_id) and exists(select 1 from public.inventory_items p where p.id=t.inventory_item_id and p.business_id=p_business_id)) r),
'products',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."name" as "name",t."sku" as "sku",t."category" as "category",t."price"::text as "price",t."active" as "active",t."description" as "description",t."image_url" as "image_url",t."created_at" as "created_at",t."updated_at" as "updated_at" from public."products" t where t.business_id=p_business_id) r),
'purchase_order_items',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."purchase_order_id" as "purchase_order_id",t."inventory_item_id" as "inventory_item_id",t."qty_ordered"::text as "qty_ordered",t."unit" as "unit",t."unit_cost"::text as "unit_cost",t."received_qty"::text as "received_qty" from public."purchase_order_items" t where exists(select 1 from public.purchase_orders p where p.id=t.purchase_order_id and p.business_id=p_business_id)) r),
'purchase_order_payments',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."purchase_order_id" as "purchase_order_id",t."amount"::text as "amount",t."payment_method" as "payment_method",t."status" as "status",t."paid_by" as "paid_by",t."paid_at" as "paid_at",t."reversed_at" as "reversed_at",t."reversed_by" as "reversed_by" from public."purchase_order_payments" t where exists(select 1 from public.purchase_orders p where p.id=t.purchase_order_id and p.business_id=p_business_id)) r),
'purchase_orders',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."po_number" as "po_number",t."supplier_id" as "supplier_id",t."location_id" as "location_id",t."order_date" as "order_date",t."expected_date" as "expected_date",t."status" as "status",t."payment_method" as "payment_method",t."notes" as "notes",t."discount"::text as "discount",t."tax"::text as "tax",t."reversed_at" as "reversed_at",t."reversed_by" as "reversed_by",t."created_by" as "created_by",t."created_at" as "created_at",t."updated_at" as "updated_at" from public."purchase_orders" t where t.business_id=p_business_id) r),
'sale_items',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."sale_id" as "sale_id",t."product_id" as "product_id",t."product_name_snapshot" as "product_name_snapshot",t."qty"::text as "qty",t."unit_price"::text as "unit_price",t."unit_cost_snapshot"::text as "unit_cost_snapshot" from public."sale_items" t where exists(select 1 from public.sales p where p.id=t.sale_id and p.business_id=p_business_id)) r),
'sales',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."order_no" as "order_no",t."sale_date" as "sale_date",t."location_id" as "location_id",t."channel" as "channel",t."payment_method" as "payment_method",t."employee_id" as "employee_id",t."customer_id" as "customer_id",t."subtotal"::text as "subtotal",t."discount"::text as "discount",t."tax"::text as "tax",t."total"::text as "total",t."status" as "status",t."fulfillment_status" as "fulfillment_status",t."notes" as "notes",t."cancelled_at" as "cancelled_at",t."cancelled_by" as "cancelled_by",t."created_by" as "created_by",t."created_at" as "created_at" from public."sales" t where t.business_id=p_business_id) r),
'shift_breaks',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."shift_id" as "shift_id",t."started_at" as "started_at",t."ended_at" as "ended_at" from public."shift_breaks" t where exists(select 1 from public.shifts p where p.id=t.shift_id and p.business_id=p_business_id)) r),
'shifts',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."employee_id" as "employee_id",t."location_id" as "location_id",t."status" as "status",t."clock_in_at" as "clock_in_at",t."clock_out_at" as "clock_out_at",t."notes" as "notes",t."created_at" as "created_at",t."updated_at" as "updated_at" from public."shifts" t where t.business_id=p_business_id) r),
'suppliers',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."name" as "name",t."contact_name" as "contact_name",t."phone" as "phone",t."email" as "email",t."address" as "address",t."website" as "website",t."tax_id" as "tax_id",t."payment_terms" as "payment_terms",t."default_currency" as "default_currency",t."products_supplied" as "products_supplied",t."notes" as "notes",t."active" as "active",t."created_at" as "created_at",t."updated_at" as "updated_at" from public."suppliers" t where t.business_id=p_business_id) r),
'task_activity',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."task_id" as "task_id",t."user_id" as "user_id",t."action" as "action",t."occurred_at" as "occurred_at" from public."task_activity" t where exists(select 1 from public.tasks p where p.id=t.task_id and p.business_id=p_business_id)) r),
'tasks',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."title" as "title",t."assigned_to" as "assigned_to",t."due_date" as "due_date",t."priority" as "priority",t."status" as "status",t."notes" as "notes",t."completed_at" as "completed_at",t."completed_by" as "completed_by",t."created_by" as "created_by",t."created_at" as "created_at",t."updated_at" as "updated_at" from public."tasks" t where t.business_id=p_business_id) r),
'users',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."employee_id" as "employee_id",t."name" as "name",t."username" as "username",t."role" as "role",t."permission_overrides" as "permission_overrides",t."active" as "active",t."created_at" as "created_at",t."updated_at" as "updated_at" from public."users" t where t.business_id=p_business_id) r),
'waste_transactions',(select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) from (select t."id" as "id",t."business_id" as "business_id",t."inventory_item_id" as "inventory_item_id",t."location_id" as "location_id",t."qty"::text as "qty",t."unit" as "unit",t."reason" as "reason",t."cost"::text as "cost",t."notes" as "notes",t."inventory_transaction_id" as "inventory_transaction_id",t."created_by" as "created_by",t."created_at" as "created_at" from public."waste_transactions" t where t.business_id=p_business_id) r)) into v_data;
 select jsonb_object_agg(key,jsonb_array_length(value)),sum(jsonb_array_length(value)) into v_counts,v_total from jsonb_each(v_data);
 if v_total>50000 or exists(select 1 from jsonb_each(v_data) where jsonb_array_length(value)>10000) or octet_length(v_data::text)>20971520 then raise exception 'Export exceeds supported size; use an operator-managed database backup' using errcode='54000'; end if;
 return jsonb_build_object('format','nexalvo-business-data','formatVersion',1,'businessId',p_business_id,'generatedAt',to_char(statement_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'data',v_data,'counts',v_counts,'excluded',jsonb_build_array('auth','storage_files','infrastructure','global_permissions','platform_administration'));
end; $function$
;

